export function validate(action:any){
 if(!action) return false;
 if(action.value && action.value < 0) return false;
 if(action.type === 'trade' && action.price <= 0) return false;
 return true;
}

server/arelogic/graph.engine.ts.content:
export class Graph {
 nodes = new Map();
 edges:any[] = [];
 addNode(n:any){ this.nodes.set(n.id,n); }
 addEdge(e:any){ this.edges.push(e); }
 relations(id:string){ return this.edges.filter(e=>e.source===id||e.target===id); }
 value(id:string){ return this.relations(id).reduce((s,e)=>s+e.weight,0); }
}

